pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(bool burnAsOwner, uint256 initialMint) public {
        vm.assume(initialMint > 0 && initialMint < 1e36);
        // Setup: give some balance to owner (msg.sender) via mint
        vm.prank(address(this));
        c.mintToken(address(this), initialMint);

        if (burnAsOwner) {
            // owner burns their own tokens
            c.burn(initialMint);
        } else {
            // non-owner attempts burn
            vm.prank(address(0x1234));
            c.burn(initialMint);
        }

        // Compute sum of owner balance (this contract) and a zero-balance check
        uint256 ownerBal = c.balanceOf(address(this));
        // In correct version, only owner can burn, so totalSupply = ownerBal (since no other balances exist).
        // In buggy version, non-owner can burn owner's tokens, so totalSupply decreases while ownerBal remains initialMint.
        assertTrue(c.totalSupply() == ownerBal);
    }
}

